// Data layer that loads from agriscope.db (SQLite, generated by refresh-data.py)
// Falls back to embedded baseline data if the live file is missing

import fs from "fs";
import path from "path";
import { fileURLToPath } from "url";
import Database from "better-sqlite3";

// ──────────────────── Types ────────────────────

type CropTimeSeries = Record<string, number>;
type CropElements = { production: CropTimeSeries; yield: CropTimeSeries; area: CropTimeSeries };
type CountryCrops = Record<string, CropElements>;

export interface DataMetadata {
  lastUpdated: string;
  sources: Record<string, { name: string; url: string; description: string; status: string }>;
  countries: { name: string; code: string; region: string }[];
  crops: string[];
  years: string[];
  errors: string[];
}

export interface BestPrice {
  price: number;
  year: string;
  source: string;       // e.g. "FAOSTAT 2024" or "West Africa avg"
  isEstimate: boolean;
  isProcessedProxy: boolean;  // true when e.g. Maize flour → Maize grain
}

// ──────────────────── SQLite Connection ────────────────────

const __filename_esm = typeof __filename !== 'undefined' ? __filename : fileURLToPath(import.meta.url);
const __dirname_esm = typeof __dirname !== 'undefined' ? __dirname : path.dirname(__filename_esm);
const DB_PATH = path.join(__dirname_esm, "data", "agriscope.db");

let dbInstance: Database.Database | null = null;
let dbVerified = false;

function getDb(): Database.Database | null {
  if (dbVerified && dbInstance) return dbInstance;
  
  if (!fs.existsSync(DB_PATH)) {
    console.warn("[data] agriscope.db not found at", DB_PATH);
    return null;
  }
  
  try {
    const conn = new Database(DB_PATH, { readonly: true });
    conn.prepare("SELECT 1 FROM metadata LIMIT 1").get();
    dbInstance = conn;
    dbVerified = true;
    return dbInstance;
  } catch (e) {
    console.warn("[data] Failed to open agriscope.db:", e);
    return null;
  }
}

function getMetadataValue<T>(key: string, parseJson = true): T | null {
  const c = getDb();
  if (!c) return null;
  const row = c.prepare("SELECT value FROM metadata WHERE key = ?").get(key) as { value: string } | undefined;
  if (!row) return null;
  return (parseJson ? JSON.parse(row.value) : row.value) as T;
}

// ──────────────────── Exported Data ────────────────────

export function getMetadata(): DataMetadata {
  const dbConfig = getDb();
  if (!dbConfig) {
    return {
      lastUpdated: "2022-12-31T00:00:00Z",
      sources: {},
      countries: COUNTRIES_FALLBACK.map(c => ({ name: c.name, code: c.code, region: c.region })),
      crops: [...CROPS_FALLBACK],
      years: [...YEARS_FALLBACK],
      errors: ["Live data not available, using embedded baseline"],
    };
  }
  
  return {
    lastUpdated: getMetadataValue<string>("lastUpdated", false) || "",
    sources: getMetadataValue("sources") || {},
    countries: getMetadataValue("countries") || [],
    crops: getMetadataValue("crops") || [],
    years: getMetadataValue("years") || [],
    errors: getMetadataValue("errors") || [],
  };
}

export function getCountries() {
  return getMetadataValue<any[]>("countries") || COUNTRIES_FALLBACK;
}

export function getCrops(): string[] {
  return getMetadataValue<string[]>("crops") || [...CROPS_FALLBACK];
}

export function getYears(): string[] {
  return getMetadataValue<string[]>("years") || [...YEARS_FALLBACK];
}

export function getCropData(): Record<string, CountryCrops> {
  const c = getDb();
  if (!c) return CROP_DATA_FALLBACK;
  
  const rows = c.prepare("SELECT country, crop, element, year, value FROM crop_metrics").all() as any[];
  const res: Record<string, CountryCrops> = {};
  
  for (const row of rows) {
    if (!res[row.country]) res[row.country] = {};
    if (!res[row.country][row.crop]) {
      res[row.country][row.crop] = { production: {}, yield: {}, area: {} };
    }
    const elementsTarget = res[row.country][row.crop] as any;
    if (!elementsTarget[row.element]) elementsTarget[row.element] = {};
    elementsTarget[row.element][String(row.year)] = row.value;
  }
  return res;
}

export function getGlobalAvgYields(): Record<string, number> {
  const c = getDb();
  if (!c) return GLOBAL_AVG_YIELDS_FALLBACK;
  
  const rows = c.prepare("SELECT crop, yield_hg_ha FROM global_avg_yields").all() as any[];
  const res: Record<string, number> = {};
  for (const r of rows) {
    res[r.crop] = r.yield_hg_ha;
  }
  return res;
}

