export function getWfpProxyFlags(): Record<string, Record<string, boolean>> {
  const c = getDb();
  if (!c) return {};
  const rows = c.prepare("SELECT country, crop FROM price_metrics WHERE source = 'wfp' AND is_proxy = 1 GROUP BY country, crop").all() as any[];
  const res: Record<string, Record<string, boolean>> = {};
  for (const row of rows) {
    if (!res[row.country]) res[row.country] = {};
    res[row.country][row.crop] = true;
  }
  return res;
}

/**
 * Get the best available price for a country/crop.
 * Uses actual FAOSTAT data when recent (< 5yr old).
 * Falls back to regional average from peer countries with recent data.
 */
export function getBestPrice(country: string, crop: string): BestPrice | null {
  const c = getDb();
  if (!c) return null; // Using live db for best price calculation
  
  const currentYear = new Date().getFullYear();
  const staleThreshold = currentYear - 5;

  // 1. Try actual FAOSTAT prices for this country/crop first
  const faostatRows = c.prepare("SELECT year, price_usd_tonne FROM price_metrics WHERE country = ? AND crop = ? AND source = 'faostat' AND price_usd_tonne > 0 ORDER BY year DESC").all(country, crop) as any[];
  
  if (faostatRows.length > 0) {
    const latestYear = parseInt(faostatRows[0].year);
    if (latestYear >= staleThreshold) {
      // Recent data exists. Take average of up to 3 most recent years
      const recentRows = faostatRows.slice(0, 3);
      const avgPrice = recentRows.reduce((sum, r) => sum + r.price_usd_tonne, 0) / recentRows.length;

      // Outlier check against other countries' latest recent FAOSTAT price
      const allCountriesLatest = c.prepare(`
        SELECT pm.country, pm.price_usd_tonne
        FROM price_metrics pm
        JOIN (
          SELECT country, MAX(year) as max_year
          FROM price_metrics
          WHERE crop = ? AND source = 'faostat' AND price_usd_tonne > 0
          GROUP BY country
        ) latest ON pm.country = latest.country AND pm.year = latest.max_year
        WHERE pm.crop = ? AND pm.source = 'faostat' AND pm.year >= ?
      `).all(crop, crop, staleThreshold) as any[];

      const allRecentPrices = allCountriesLatest.map(r => r.price_usd_tonne).sort((a, b) => a - b);
      let isOutlier = false;
      if (allRecentPrices.length >= 3) {
        const median = allRecentPrices[Math.floor(allRecentPrices.length / 2)];
        isOutlier = avgPrice > median * 5;
      }

      if (!isOutlier) {
        return {
          price: Math.round(avgPrice),
          year: String(latestYear),
          source: `FAOSTAT ${latestYear}`,
          isEstimate: false,
          isProcessedProxy: false,
        };
      }
    }
  }

  // 2. Try WFP prices
  const wfpRows = c.prepare("SELECT year, price_usd_tonne, is_proxy FROM price_metrics WHERE country = ? AND crop = ? AND source = 'wfp' AND price_usd_tonne > 0 ORDER BY year DESC").all(country, crop) as any[];
  
  if (wfpRows.length > 0) {
    const latestYear = parseInt(wfpRows[0].year);
    if (latestYear >= staleThreshold) {
      const recentRows = wfpRows.slice(0, 3);
      const avgPrice = recentRows.reduce((sum, r) => sum + r.price_usd_tonne, 0) / recentRows.length;
      const isProxy = recentRows[0].is_proxy === 1;
      
      const proxyLabel = isProxy ? ", flour proxy" : "";
      return {
        price: Math.round(avgPrice),
        year: String(latestYear),
        source: `WFP ${latestYear} (est. farmgate${proxyLabel})`,
        isEstimate: true,
        isProcessedProxy: isProxy,
      };
    }
  }

  // 3. Use precomputed regional/continental estimate from Python script
  const estimateRow = c.prepare("SELECT year, price_usd_tonne, source FROM price_metrics WHERE country = ? AND crop = ? AND source LIKE '%avg' ORDER BY year DESC LIMIT 1").get(country, crop) as any;
  if (estimateRow) {
    return {
      price: Math.round(estimateRow.price_usd_tonne),
      year: String(estimateRow.year),
      source: estimateRow.source,
      isEstimate: true,
      isProcessedProxy: false,
    };
  }
  
  // 4. Fallback to stale FAOSTAT data
  if (faostatRows.length > 0) {
    const recentRows = faostatRows.slice(0, 3);
    const avgPrice = recentRows.reduce((sum, r) => sum + r.price_usd_tonne, 0) / recentRows.length;
    return {
      price: Math.round(avgPrice),
      year: String(faostatRows[0].year),
      source: `FAOSTAT ${faostatRows[0].year}`,
      isEstimate: false,
      isProcessedProxy: false,
    };
  }

  return null;
}

